handy.neu:
With(
  { ab: If(ddDatum.Selected.Tag = Today(), Max(6 * 60, 30 * RoundDown((Hour(Now()) * 60 + Minute(Now())) / 30, 0)), 6 * 60) },
  ForAll(
    Sequence(Max(0, (21 * 60 + 30 - ab) / 30 + 1), 0) As n,
    {
      Value: Text(Time(RoundDown((ab + n.Value * 30) / 60, 0), Mod(ab + n.Value * 30, 60), 0), "hh:mm"),
      Min: ab + n.Value * 30
    }
  )
)

